def is_anagram(str1, str2):
    # Remove any spaces or special characters and convert to lowercase
    str1 = ''.join(char.lower() for char in str1 if char.isalpha())
    str2 = ''.join(char.lower() for char in str2 if char.isalpha())

    # Check if the two strings have the same length
    if len(str1) != len(str2):
        return False

    # Create a frequency dictionary for each string
    freq1 = {}
    freq2 = {}
    for char in str1:
        freq1[char] = freq1.get(char, 0) + 1
    for char in str2:
